
WITH /*+ SET_VAR(join_buffer_size=536870912) */ filtered_dates AS ( SELECT /*+ NO_MERGE() */ d_date_sk FROM date_dim WHERE d_year = 2001 ), filtered_hd AS ( SELECT /*+ NO_MERGE() */ hd_demo_sk, hd_dep_count FROM household_demographics WHERE hd_dep_count IN (1, 3) ), filtered_cd AS ( SELECT /*+ NO_MERGE() */ cd_demo_sk, cd_marital_status, cd_education_status FROM customer_demographics WHERE (cd_marital_status = "S" AND cd_education_status = "Secondary") OR (cd_marital_status = "U" AND cd_education_status = "4 yr Degree") OR (cd_marital_status = "W" AND cd_education_status = "2 yr Degree") ), filtered_ca AS ( SELECT /*+ NO_MERGE() */ ca_address_sk, ca_state FROM customer_address WHERE ca_country = "United States" AND ca_state IN ("IA", "MN", "MT", "AR", "IN", "TX", "TN", "NE", "WV") ) SELECT AVG(ss.ss_quantity), AVG(ss.ss_ext_sales_price), AVG(ss.ss_ext_wholesale_cost), SUM(ss.ss_ext_wholesale_cost) FROM filtered_dates d STRAIGHT_JOIN store_sales ss ON ss.ss_sold_date_sk = d.d_date_sk STRAIGHT_JOIN store s ON s.s_store_sk = ss.ss_store_sk STRAIGHT_JOIN filtered_hd hd ON ss.ss_hdemo_sk = hd.hd_demo_sk STRAIGHT_JOIN filtered_cd cd ON ss.ss_cdemo_sk = cd.cd_demo_sk STRAIGHT_JOIN filtered_ca ca ON ss.ss_addr_sk = ca.ca_address_sk WHERE ss.ss_sales_price BETWEEN 50.00 AND 200.00 AND ss.ss_net_profit BETWEEN 50 AND 300 AND ( (cd.cd_marital_status = "S" AND cd.cd_education_status = "Secondary" AND ss.ss_sales_price BETWEEN 100.00 AND 150.00 AND hd.hd_dep_count = 3) OR (cd.cd_marital_status = "U" AND cd.cd_education_status = "4 yr Degree" AND ss.ss_sales_price BETWEEN 50.00 AND 100.00 AND hd.hd_dep_count = 1) OR (cd.cd_marital_status = "W" AND cd.cd_education_status = "2 yr Degree" AND ss.ss_sales_price BETWEEN 150.00 AND 200.00 AND hd.hd_dep_count = 1) ) AND ( (ca.ca_state IN ("IA", "MN", "MT") AND ss.ss_net_profit BETWEEN 100 AND 200) OR (ca.ca_state IN ("AR", "IN", "TX") AND ss.ss_net_profit BETWEEN 150 AND 300) OR (ca.ca_state IN ("TN", "NE", "WV") AND ss.ss_net_profit BETWEEN 50 AND 250) );
